from PIL import Image,ImageDraw,ImageFont
from pathlib import Path
P=Path(__file__).resolve().parent.parent; W,H=1240,1754
R='/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'; B='/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'
def font(n,b=False):return ImageFont.truetype(B if b else R,n)
def wrap(d,s,ft,m):
 out=[]; line=''
 for word in s.split():
  t=(line+' '+word).strip()
  if d.textbbox((0,0),t,font=ft)[2]>m and line:out.append(line);line=word
  else:line=t
 if line:out.append(line)
 return out
def txt(d,s,x,y,n=25,b=False,c='#203e37',m=1020,lead=1.34):
 ft=font(n,b)
 for line in wrap(d,s,ft,m):d.text((x,y),line,font=ft,fill=c);y+=int(n*lead)
 return y
def base(num,heading,subtitle):
 im=Image.new('RGB',(W,H),'#f8f6f0');d=ImageDraw.Draw(im)
 d.rounded_rectangle((38,35,1202,1719),radius=32,outline='#9dbd9a',width=4)
 d.rounded_rectangle((74,68,1166,144),radius=18,fill='#e5eddf')
 txt(d,'PLANT MATRIX  ·  НАУЧНЫЙ АТЛАС 01',94,87,24,True,'#2e644c')
 txt(d,heading,80,179,46,True,'#173f32',1080,1.17)
 y=txt(d,subtitle,82,250,22,False,'#61786e',1050,1.32)+28
 d.line((80,1652,1160,1652),fill='#b6cbae',width=3)
 txt(d,f'НУТРИЦИОЛОГИЯ · БИОХАКИНГ · ОБЩЕОБРАЗОВАТЕЛЬНЫЙ МАТЕРИАЛ   {num}/7',84,1670,17,True,'#6f8779',1080)
 return im,d,y
def block(d,y,title,body,color='#ecf2e8',size=25):
 n=len(wrap(d,body,font(size),985));h=71+n*int(size*1.34)+25
 d.rounded_rectangle((79,y,1161,y+h),radius=20,fill=color,outline='#c7d8c1',width=2)
 txt(d,title,103,y+18,28,True,'#245642')
 txt(d,body,103,y+65,size,False,'#263f38',985)
 return y+h+16
pages=[]
